mapper.update:
UPDATE rx_operation
SET status = #{targetStatus}, version = version + 1, updated_at = NOW()
WHERE id = #{id} AND version = #{currentVersion}

UPDATE rx_operation
SET retry_count = retry_count + 1, status = 'RETRYING', updated_at = NOW()
WHERE id = #{id}

UPDATE rx_operation
SET started_at = #{startedAt}, updated_at = NOW()
WHERE id = #{id}

UPDATE rx_operation
SET current_step = #{currentStep}, updated_at = NOW()
WHERE id = #{id}

UPDATE rx_operation
SET completed_at = #{completedAt}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT * FROM rx_operation
WHERE status = 'RUNNING'
  AND started_at IS NOT NULL
  AND started_at < #{threshold}
ORDER BY started_at ASC
LIMIT #{limit}
